"""Contract tests for the About & Help pages generated by scripts/build_about.py."""
import importlib.util
import json
import re
import sys
import tempfile
import unittest
from html.parser import HTMLParser
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "scripts"))
import build_about  # noqa: E402

PAGES = ["", "using", "songs", "schedule", "faq", "privacy", "accessibility", "whats-new"]


class Doc(HTMLParser):
    def __init__(self):
        super().__init__()
        self.links, self.ids, self.scripts, self.imgs, self.h1 = [], set(), [], [], 0
        self.meta, self.title, self._in_title = {}, "", False

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if "id" in a:
            self.ids.add(a["id"])
        if tag == "a" and "href" in a:
            self.links.append(a)
        elif tag == "script":
            self.scripts.append(a)
        elif tag == "img":
            self.imgs.append(a)
        elif tag == "h1":
            self.h1 += 1
        elif tag == "meta":
            self.meta[a.get("name") or a.get("property")] = a.get("content")
        elif tag == "title":
            self._in_title = True

    def handle_endtag(self, tag):
        if tag == "title":
            self._in_title = False

    def handle_data(self, data):
        if self._in_title:
            self.title += data


class AboutSite(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.tmp = tempfile.TemporaryDirectory()
        cls.out = Path(cls.tmp.name)
        cls.result = build_about.build(cls.out)
        cls.docs = {}
        for slug in PAGES:
            path = cls.out / "about" / slug / "index.html" if slug else cls.out / "about" / "index.html"
            d = Doc()
            d.text = path.read_text(encoding="utf-8")
            d.feed(d.text)
            cls.docs[slug] = d
        perf = json.loads((ROOT / "data/edco-2026/current-lineup.json").read_text(encoding="utf-8"))["performances"]
        artists = json.loads((ROOT / "data/edco-2026/artists.json").read_text(encoding="utf-8"))["artists"]
        cls.app_ids = {p["performance_id"] for p in perf} | {a["artist_id"] for a in artists}
        cls.perf = perf

    @classmethod
    def tearDownClass(cls):
        cls.tmp.cleanup()

    def test_every_page_is_complete(self):
        for slug, d in self.docs.items():
            with self.subTest(page=slug or "overview"):
                self.assertEqual(d.h1, 1)
                self.assertTrue(d.title.strip())
                self.assertTrue(d.meta.get("description"))
                self.assertEqual(d.meta.get("og:image"), "https://listeningroom.app/og.png")
                self.assertNotIn("{{", d.text)
                self.assertIn("Independent and unofficial", d.text)

    def test_scripts_are_local_files_only(self):
        # The site CSP is script-src 'self': inline scripts would be blocked.
        for slug, d in self.docs.items():
            self.assertEqual([s.get("src") for s in d.scripts], ["/about/assets/about.js"], slug)
            self.assertNotRegex(d.text, r"<script(?![^>]*\bsrc=)")
            self.assertNotIn(" on" + "click=", d.text)
        self.assertNotIn("data:image", (self.out / "about/assets/about.css").read_text(encoding="utf-8"))

    def test_internal_links_and_anchors_resolve(self):
        for slug, d in self.docs.items():
            for a in d.links:
                href = a["href"]
                if href.startswith("#"):
                    self.assertIn(href[1:], d.ids, f"{slug}: {href}")
                elif href.startswith("/about/"):
                    path, _, anchor = href.partition("#")
                    target = path.strip("/").removeprefix("about").strip("/")
                    self.assertIn(target, self.docs, f"{slug}: {href}")
                    if anchor:
                        self.assertIn(anchor, self.docs[target].ids, f"{slug}: {href}")
                elif href.startswith("/listening-room/"):
                    m = re.match(r"^/listening-room/(#/(lineup|listen|artist/([^?]+))(\?.*)?)?$", href)
                    self.assertTrue(m, f"{slug}: {href}")
                    if m and m.group(3):
                        self.assertIn(m.group(3), self.app_ids, f"{slug}: {href}")
                elif href.startswith("http"):
                    self.assertTrue(href.startswith("https://"), href)
                    self.assertEqual(a.get("target"), "_blank", href)
                    self.assertIn("noopener", a.get("rel", ""), href)
                else:
                    self.fail(f"{slug}: unexpected link {href}")

    def test_images_exist_with_alt_text_and_dimensions(self):
        for slug, d in self.docs.items():
            for img in d.imgs:
                self.assertTrue(img.get("alt"), f"{slug}: {img}")
                self.assertTrue(img.get("width") and img.get("height"), f"{slug}: {img}")
                self.assertTrue((self.out / img["src"].lstrip("/")).is_file(), img["src"])
        for name in ("favicon.svg", "apple-touch-icon.png", "og.png"):
            self.assertTrue((self.out / name).is_file(), name)

    def test_live_numbers_come_from_the_data(self):
        stats = self.result["stats"]
        self.assertEqual(stats["lineup_entries"], len(self.perf))
        self.assertIn(f"<b>{len(self.perf)}</b>", self.docs[""].text)
        songs = json.loads((ROOT / "data/listening-room/songs.json").read_text(encoding="utf-8"))["songs"]
        self.assertEqual(stats["songs"], len(songs))
        for s in songs:
            self.assertIn(s["url"], self.docs["songs"].text)

    def test_playlist_copy_matches_its_status(self):
        pl = json.loads((ROOT / "data/listening-room/playlist.json").read_text(encoding="utf-8"))
        text = self.docs["faq"].text
        if pl.get("status") == "published" and pl.get("verified_cross_account"):
            self.assertNotIn("not available yet", text)
        else:
            self.assertIn("not available yet", text)
            self.assertNotIn("music.youtube.com/playlist", text)

    def test_search_index_covers_pages_and_lineup(self):
        idx = json.loads((self.out / "about/search.json").read_text(encoding="utf-8"))
        urls = {row["url"].split("#")[0] for row in idx if not row.get("act")}
        self.assertEqual(urls, {"/about/" + (s + "/" if s else "") for s in PAGES})
        self.assertEqual(sum(bool(row.get("act")) for row in idx), len(self.perf))

    def test_no_private_data_or_fake_features(self):
        blob = "".join(p.read_bytes().decode("utf-8", "ignore") for p in self.out.rglob("*") if p.is_file())
        for banned in ("app.notion.com", "notion_page_url", "PLdOAWVle", "youtube.com/results"):
            self.assertNotIn(banned, blob)

    def test_quoted_interface_copy_still_exists_in_the_app(self):
        # Help pages quote on-screen wording ({{ui ...}}). If the app's copy changes, update
        # about-site/pages/* to match (and refresh screenshots: about-site/README.md).
        app = "".join((ROOT / "listening-room" / f).read_text(encoding="utf-8") for f in ("app.js", "lib.js", "index.html"))
        self.assertTrue(self.result["ui_strings"])
        missing = [s for s in self.result["ui_strings"] if s not in app]
        self.assertEqual(missing, [], "About pages quote UI copy the app no longer shows; update about-site/pages")

    def test_screenshots_ship_only_while_they_match_the_app(self):
        shots = json.loads((ROOT / "about-site/img/shots.json").read_text(encoding="utf-8"))
        imgs = [i for d in self.docs.values() for i in d.imgs if i["src"].startswith("/about/img/")]
        if shots.get("_app") == build_about.app_fingerprint():
            self.assertGreaterEqual(len(imgs), len([k for k in shots if not k.startswith("_")]))
        else:  # the app changed after the capture: no stale screens, the guide still works on links alone
            self.assertEqual(imgs, [])
        stale = build_about.Renderer(build_about.Data(), [{"slug": "", "title": "t", "nav": "t", "description": "d",
                                                           "file": "x", "url": "/about/", "body": ""}], {"_app": "old"})
        self.assertEqual(stale.shot(stale.pages[0], "lineup", "alt"), "")

    def test_search_examples_find_someone(self):
        r = build_about.Renderer(build_about.Data(), [{"slug": "", "title": "t", "nav": "t", "description": "d",
                                                       "file": "x", "url": "/about/", "body": ""}], {})
        self.assertTrue(r.search_hits("obskur"), "accent-insensitive search example")
        with self.assertRaises(build_about.BuildError):
            r.app_href("lineup?q=zzqqxx")

    def test_unknown_directive_fails_the_build(self):
        r = build_about.Renderer(build_about.Data(), [{"slug": "", "title": "t", "nav": "t", "description": "d", "file": "x",
                                                       "url": "/about/", "body": "{{nope}}"}], {})
        with self.assertRaises(build_about.BuildError):
            r.body(r.pages[0])
        with self.assertRaises(build_about.BuildError):
            r.app_href("artist/not-a-real-act")


class PublicBuildIncludesAbout(unittest.TestCase):
    def test_public_build_ships_about_pages(self):
        spec = importlib.util.spec_from_file_location("build_public_site", ROOT / "scripts" / "build_public_site.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        with tempfile.TemporaryDirectory() as tmp:
            mod.OUT = Path(tmp) / "public-site"
            mod.build()
            for rel in ("about/index.html", "about/faq/index.html", "about/search.json", "favicon.svg", "og.png",
                        "listening-room/index.html"):
                self.assertTrue((mod.OUT / rel).is_file(), rel)


if __name__ == "__main__":
    unittest.main()
